INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('apex-rebels', 275576, '2024-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97p8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3725.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apex Rebels', 'Players can control their racing destiny by choosing from five high-octane vehicles. At the start of each lap, they must pass through one of three checkpoints that will determine the driving route best suited for their racing style. Passing through progressive checkpoints gives speed boosts and unlocks advanced skills like Slipstream, Power Drifts, and Aero-Drifts. Aero-Drift is a ground-breaking technique that raises the car, allowing players to race through corners at blazing speeds, effortlessly overtaking their rivals. Every aspect of gameplay is designed to be thrilling and encourages a competitive spirit that sees players take down their rivals and jump into slipstreams to earn an extra boost, giving them an edge to seize victory!' FROM games WHERE igdb_id = 275576 ON CONFLICT (game_id, language_code) DO NOTHING;
