INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trench Warfare WW1: RTS Battle', 'As a WWI general, command your army across trenches in the Eastern Front and Western Front, experiencing real-life historical battles as both the Allies and Central powers. Engage in real time strategy (RTS) where your objective is to select the right combination of soldiers and tanks to conquer the enemy trenches. Survive wave upon wave of enemy soldiers as they try to gain supremacy and use tactical artillery strikes to support your army. Choose your side from a variety of WWI nations including the British, Germans, French, and Ottoman military. Simulate battles such as Somme, Verdun, and Gallipoli, experiencing total war. In Trench Warfare WWI your goal is to gain supremacy by capturing the enemy trenches and seeing your nations flag wave in the wind. Use RTS strategy and battle alongside your allies army in the trenches of total war!' FROM games WHERE igdb_id = 303792 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 303792 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
