INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat Crunch', 'Welcome to "Cat Crunch," a captivating match-3 game where strategy and fun come together in over 3500 levels of feline-themed puzzles. Dive into an immersive world where your goal is not only to match blocks but also to grow your adorable cat, earning combo rewards and unleashing powerful line blasters. With no timer to rush you, each move can be strategic, allowing for a more relaxed yet engaging gameplay experience.' FROM games WHERE igdb_id = 304955 ON CONFLICT (game_id, language_code) DO NOTHING;
