INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snakslad', 'A simple simulation of the classic game of Snakes and Ladders. Choose your piece (+ or *) and then hit a key to role a dice for each. The winner is the player who makes it to the last (red) square first. If you land on the head of a snake, you slide down to the bottom of its tail. If you land at the bottom of a ladder, you ascend to the top of it.' FROM games WHERE igdb_id = 289111 ON CONFLICT (game_id, language_code) DO NOTHING;
