INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZXFM', 'ZXFM is a football management simulator for the Sinclair ZX Spectrum written in just 10 lines of BASIC! Play an entire season as manager of a team from your favourite league, or create your own leagues and teams. Manage injuries, buy and sell in the transfer market and save your progress to tape or disk as you go along. ZXFM was inspired by the original 1982 "Football Manager" game by Kevin Toms (which was also written in BASIC but used over 700 lines of code!)' FROM games WHERE igdb_id = 289114 ON CONFLICT (game_id, language_code) DO NOTHING;
