INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hermano', 'Journey through the afterlife in Hermano, an exciting multi-scroller platformer for the original Game Boy. With pixel-perfect graphics and chiptune soundtrack, experience the magic and mystery of Día de Muertos. Traverse 15 main levels and 4 bonus stages across scrolling 2D landscapes. Avoid traps and defeat over 15 types of enemies, including 3 epic boss battles. Hermano mixes platforming action with puzzles, exploration, and gravity-defying gameplay for a fresh take on classic sidescrollers. With an authentic pixel-art style and fantastical themes.' FROM games WHERE igdb_id = 299857 ON CONFLICT (game_id, language_code) DO NOTHING;
