INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teletext', 'Welcome back to 1995. You turn your TV on, but there''s an ad break! You press the red button to check out your favorite passtime. As you browse through, you see there''s a lot missing. News articles not displaying, games out of order. Is anyone even keeping this updated anymore? Where did they go?' FROM games WHERE igdb_id = 286903 ON CONFLICT (game_id, language_code) DO NOTHING;
