INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prison X: Chapter 1 - The Devil and The Sun', 'Heavy doors open and you''re swept into the surreal world of Prison X, an infamous Bolivian jail in the Neo-Andean underworld. As you navigate amongst devils, saints, wicked characters, corrupt prison guards and even a Western filmmaker; hold onto your soul so La Diabla doesn''t snatch it away.' FROM games WHERE igdb_id = 326220 ON CONFLICT (game_id, language_code) DO NOTHING;
