INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Driver Go', 'Truck Driver Go is a free-to-play driving sim mobile game where you''ll take on various trucking missions, explore different locations, and follow a compelling narrative. Truck Driver Go offers the ultimate truck-driving experience inspired by the hit game Truck Driver game. Take on the role of David, who sets out to restore his father’s legacy and make a mark in trucking history. Embark on an emotional journey as you follow an intriguing narrative, while transporting different cargo across a network of roads.' FROM games WHERE igdb_id = 320383 ON CONFLICT (game_id, language_code) DO NOTHING;
