INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Nun: The Broken Mask - Unholy Edition', 'Evil Nun: The Broken Mask – Unholy Edition is a first-person horror game where players try to escape a haunted school while avoiding Sister Madeline, an AI-driven enemy who reacts to the player’s actions. The gameplay involves solving puzzles, crafting items, and exploring different escape paths. It’s based on the original mobile game series and includes updated graphics, new areas, and an expanded story. The Unholy Edition includes a slipcover, digital soundtrack, camp admission letter, art book, and the game disc.' FROM games WHERE igdb_id = 324596 ON CONFLICT (game_id, language_code) DO NOTHING;
