INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-steel-empire', 270587, '2024-01-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7mut.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2p5v.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Steel Empire', 'In a dystopian world where the Motorhead Empire has conquered and enslaved virtually the entire planet, mammoth battleships, armored locomotives, and invincible fortresses dominate the skies. However, there is hope for the republic of Silverhead, and you are the only one who can save it. Take control of the Striker airplane or Zeppelin with an aerial mine launcher and engage in intense euro-shmup action, battling enemies both in the air and on the ground, and using devastating screen-clearing attacks in tight spots. With improved graphics and controls, Steel Empire, originally released in the early 90s for a 16-bit console, has been ported to various handheld consoles. Join the fight and defeat the Motorhead Empire.' FROM games WHERE igdb_id = 270587 ON CONFLICT (game_id, language_code) DO NOTHING;
