INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growth Spurt: A Meandering Intermission into the Afterhours of a Miscalculation', 'A faux pas at the Middle School dance reverts Nour back to their primordial state and sends them on a one-night maximalist transformative journey. Flop, slide, leap, and rocket around the city filled with zany future friends and mysterious architectures. Play eclectic mini-games where you will discover whether surgery can be joyful, if aliens have feelings, and how to deal with a bad boss.' FROM games WHERE igdb_id = 301910 ON CONFLICT (game_id, language_code) DO NOTHING;
