INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cast Dice Away', 'A board game-style survival adventure on a deserted island! In Cast Dice Away, roll dice to explore the island, gather resources, and survive. Each roll triggers unpredictable events, challenging you to strategically navigate diverse environments as you seek escape.' FROM games WHERE igdb_id = 324901 ON CONFLICT (game_id, language_code) DO NOTHING;
