INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meow Playground', 'Meow Playground is an online game that lets you play as a cute animal character. In the game, you have the opportunity to improve your character, communicate with other players, and participate in a variety of games and activities, such as fishing or playing tag and dodgeball. Additionally, you can customize and decorate your own house to your liking. With so many options and possibilities, Meow Playground offers endless fun for anyone who loves animals and online gaming!' FROM games WHERE igdb_id = 168543 ON CONFLICT (game_id, language_code) DO NOTHING;
