INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beauties! They''re All After Me', 'In this thrilling romance game, players are a working-class hero meeting six girls: a loli, a mature woman, a housewife, a soft girl, a domineering CEO, and a cute, naive girl. As he gets involved with them, he awakens a cheating system—can you believe it?! Make your final choice now!' FROM games WHERE igdb_id = 306240 ON CONFLICT (game_id, language_code) DO NOTHING;
