INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob: Bubble Pop F.U.N.', 'SpongeBob: Bubble Pop F.U.N. is a classic match-three puzzle game with a couple of clever twists. Similar to classics like Puzzle Bobble, the playing field is set before you start, and it’s your job to fire red, green, blue, purple, and yellow bubbles at the ones hovering above your porous yellow skull. You can bank shots off the walls, and you fire by holding your finger on the screen and pulling back.' FROM games WHERE igdb_id = 320381 ON CONFLICT (game_id, language_code) DO NOTHING;
